\subsection{Structural Result for AM Circuits}
The AM circuit representation allows us to study a verifier's acceptance probability through a convex function, but the presence of MAX gates makes this function non-differentiable, thereby complicating our analysis. To recover differentiability, we replace the MAX gates by smooth approximations, i.e. softmax gates. The following lemma shows that this replacement preserves convexity, and gives explicit bounds on the approximation error as well as gradient and Hessian norms in terms of the circuit parameters.

\begin{lemma}[Softmax smoothing]\label{lemma:structural}
Let $C$ be a $(d, L)$-AM circuit which takes inputs $x \in \{\pm 1\}^m$. Then for every $\lambda > 0$, there is a smooth convex function $F: \bbR^m \to \bbR$ such that $0 \leq F-C \leq \frac{dL \ln 2}{\lambda}$, $\sup_x \|\nabla F(x)\|_1 \leq L$, and $\sup_x \|\nabla^2 F(x)\|_1 \leq 2\lambda dL^2$.
\end{lemma}
\begin{proof}
Begin by replacing each MAX gate in $C$ by the softmax gate
    \[ S_\lambda(u_1, \ldots, u_k) = \lambda^{-1}\ln(\sum_{i = 1}^k e^{\lambda u_i}). \]
Observe that
    \[ \max(u_1, \ldots, u_k) \leq S_\lambda(u_1, \ldots, u_k) \leq \max(u_1, \ldots, u_k)+\frac{\ln k}{\lambda} \leq \max(u_1, \ldots, u_k)+\frac{L \ln 2}{\lambda}. \]

For a gate $v$ in the circuit, denote by $C_v(x)$ the value of the gate on input $x$ in the original circuit $C$ and by $F_v(x)$ the value of the corresponding gate in the new circuit with softmax gates.

We show by induction on the MAX-gate height $h$ that for every gate $v$ at MAX-gate height $h$, $0 \leq F_v(x)-C_v(x) \leq hL\ln(2)/\lambda$. The claim is obvious at height $h = 0$, and also clearly follows for any AVG gate, so it remains to prove it for MAX gates at height $h \geq 1$.

For $h \geq 1$, let $v$ be a MAX gate at height $h$ and let $u_1, \ldots, u_k$ be the gates, each of height at most $h-1$, entering the gate $v$. On the one hand, 
    \[ C_v(x) = \max(C_{u_1}(x), \ldots, C_{u_k}(x))  \leq \max(F_{u_1}(x), \ldots, F_{u_k}(x)) \leq S_{\lambda}(F_{u_1}(x), \ldots, F_{u_k}(x)) = F_v(x). \]
On the other hand,
\begin{align*}
    F_v(x) &= S_{\lambda}(F_{u_1}(x), \ldots, F_{u_k}(x)) \\
    &\leq \max(F_{u_1}(x), \ldots, F_{u_k}(x)) + \frac{L\ln2}{\lambda} \\
    &\leq \max(C_{u_1}(x) + \tfrac{(h-1)L\ln2}{\lambda}, \ldots, C_{u_k}(x) + \tfrac{(h-1)L\ln2}{\lambda}) + \frac{L\ln2}{\lambda} \\
    &= \max(C_{u_1}(x), \dots, C_{u_k}(x)) + \frac{hL\ln2}{\lambda} \\
    &= C_v(x) + \frac{hL\ln2}{\lambda},
\end{align*}
which concludes the inductive proof. Smoothness follows from the fact that all gates (softmax, AVG, affine leaves) are smooth, and smoothness is preserved by composition.

For child functions $u_1, \ldots, u_k$, writing $p_i = \frac{e^{\lambda u_i}}{\sum_j e^{\lambda u_j}}$ we have that
\begin{align*}
    \nabla S_\lambda &= \sum_i p_i \nabla u_i.
\end{align*}
Hence, if every child $u_i$ satisfies $\|\nabla u_i\|_1 \leq L$, then
    \[ \|\nabla S_\lambda\|_1 \leq \sum_i p_i \|\nabla u_i\|_1 \leq L. \]
Likewise, at an AVG gate,
    \[ \operatorname{AVG}(u_1, \ldots, u_k) = \frac{1}{k} \sum_i u_i, \]
and thus
    \[ \nabla \operatorname{AVG} = \frac{1}{k} \sum_i \nabla u_i, \]
which means the gradient norm bound is also preserved by AVG gates. Starting from the affine leaves, which have $\ell_1$-gradient norm at most $L$, proves that $\sup_x \|\nabla F(x)\|_1 \leq L$.

Differentiating $\nabla S_{\lambda}$ gives
    \[ \nabla^2 S_\lambda = \sum_i p_i \nabla^2 u_i + \sum_i \nabla u_i (\nabla p_i)^\sfT. \]
To evaluate this, we first determine the gradient of $p_i$: 
\begin{align*}
    \nabla p_i &= \frac{(\sum_j e^{\lambda u_j}) \cdot \lambda  e^{\lambda u_i} \cdot \nabla u_i - e^{\lambda u_i} \cdot \sum_j (\lambda e^{\lambda u_j} \cdot \nabla u_j)}{(\sum_r e^{\lambda u_r})^2} \\
    &= \frac{\lambda e^{\lambda u_i} \cdot \nabla u_i}{\sum_r e^{\lambda u_r}} - \frac{\lambda e^{\lambda u_i}}{\sum_r e^{\lambda u_r}} \cdot \frac{\sum_j (e^{\lambda u_j} \cdot \nabla u_j)}{\sum_r e^{\lambda u_r}} \\
    &= \lambda p_i \nabla u_i - \lambda p_i \cdot \left(\sum_j p_j \nabla u_j\right).
\end{align*}
Thus,
\begin{align*}
    \nabla^2 S_\lambda &= \sum_i p_i \nabla^2 u_i + \sum_i  \nabla u_i (\nabla p_i)^\sfT \\
    &= \sum_i p_i \nabla^2 u_i + \sum_i \lambda p_i \nabla u_i (\nabla u_i - \sum_j p_j \nabla u_j)^\sfT \\
    &= \sum_i p_i \nabla^2 u_i + \lambda \left[\sum_i p_i \nabla u_i (\nabla u_i)^\sfT - \sum_{i, j} p_i p_j \nabla u_i (\nabla u_j)^\sfT\right] \\
    &= \sum_i p_i \nabla^2 u_i + \frac{\lambda}{2} \sum_{i, j} p_i p_j (\nabla u_i - \nabla u_j)(\nabla u_i - \nabla u_j)^\sfT.
\end{align*}
The last term is positive semidefinite, which proves convexity by induction on the depth of $C$, as the leaves of $C$ are convex.

To bound the Hessian norm, we note that
\begin{align*}
    \|\nabla^2 S_\lambda\|_1 &\leq \sum_i p_i \|\nabla^2 u_i\|_1 + \frac{\lambda}{2} \sum_{i, j} p_i p_j \|(\nabla u_i - \nabla u_j)(\nabla u_i - \nabla u_j)^\sfT\|_1 \\
    &\leq \sum_i p_i \|\nabla^2 u_i\|_1 + \frac{\lambda}{2} \sum_{i, j} p_i p_j \|\nabla u_i - \nabla u_j\|_1^2 \\
    &\leq \sum_i p_i \|\nabla^2 u_i\|_1 + \frac{\lambda}{2} \sum_{i, j} p_i p_j (2L)^2 = \sum_i p_i \|\nabla^2 u_i\|_1 + 2\lambda L^2,
\end{align*}
so softmax gates increase the Hessian norm by at most $2\lambda L^2$. Meanwhile, for an AVG gate,
    \[ \|\nabla^2 \operatorname{AVG}\|_1 \leq \frac{1}{k} \sum_i \|\nabla^2 u_i\|_1, \]
so average gates do not increase the Hessian norm. Since the leaves have zero Hessian norm, we have by induction on the depth of $C$ that $\sup_x \|\nabla^2 F(x)\|_1 \leq 2\lambda dL^2$.
\end{proof}

\begin{remark}

Convexity is essential to our use of the derivative bounds. Indeed, Appendix \ref{sec:smooth-extensions} shows that every function \(f:\{\pm1\}^m\to[-1,1]\) admits a smooth extension \(F:\mathbb R^m\to[-1,1]\) agreeing exactly with \(f\) on the Boolean cube and satisfying
\[
\sup_x\|\nabla F(x)\|_1\le2,
\qquad
\sup_x\|\nabla^2F(x)\|_1\le C\log(2m),
\]
where the Hessian norm is the entrywise \(\ell_1\)-norm and \(C\) is an absolute constant. Thus even a dimension-independent gradient bound and a logarithmic Hessian bound are compatible with arbitrary Boolean behavior. The crucial property of our construction is achieving the required derivative control simultaneously with convexity.
\end{remark}

\subsection{Notation}\label{section:notation}
In the following section, we will use $\delta$-smoothings of the function $f_{a}(x) := \sgn(a+x)$ for any fixed $a \in \bbR^m$. Specifically, for any $\delta \in (0, 1]$ and real vector $a \in \bbR^m$, we define the functions
\begin{align*}
    h_{a, \delta, i}(t) &:= 2\Phi\left(\frac{a_i + \sqrt{1-\delta^2} t}{\delta}\right)-1, &\text{for $i\in [m]$}\\
    h_{a, \delta}(x) &:= (h_{a, \delta, 1}(x_1), \ldots, h_{a, \delta, m}(x_m)).
\end{align*}
Observe that $h_{a, \delta, i}(t) \in [-1, 1]$ and 
\begin{align*}
    |h_{a, \delta, i}'(t)| = \left|\tfrac{2\sqrt{1-\delta^2}}{\delta}\cdot 
       \varphi\left(\tfrac{a_i + \sqrt{1-\delta^2}t}{\delta}\right)\right| \leq \sqrt{\frac{2}{\pi}} \cdot \frac{1}{\delta} \leq \frac{1}{\delta}.
\end{align*}
Further, observe that there is another way to derive $h_{a,\delta}(x)$ as \[h_{a,\delta}(x) = \E[\sgn(a + \sqrt{1-\delta^2}x + \delta G')]\] for any MVG $G'$ of dimension $m$ with zero means and variances $1$ (and arbitrary covariances as we only care about the expectation coordinate-wise).

\subsection{Forrelated Gaussians Fool AM Circuits}

The following lemma provides the key technical insight required in the proof of our main result. The lemma bounds the change in the expected value of a
smooth convex function $F$ when Gaussian sign rounding is replaced
by a smooth approximation: it shows that
$\bbE[F(\sgn(a+G))]$ and
$\bbE[F(h_{a,\delta}(G))]$ are close under the stated assumptions. Here, $G$ is a nondegenerate Gaussian vector with standard normal marginals, and $h_{a,\delta}$ is the coordinate-wise smooth approximation to sign rounding defined in Section~\ref{section:notation}.

The error is controlled by the $\ell_1$-gradient bound of $F$ and the smoothing parameter $\delta$, with only a logarithmic dependence on the input dimension $m$. Crucially, this lemma uses the convexity of $F$ to get a better bound than would be implied by a naive application of H\"older's inequality. In our application, $F$ is the smooth approximation to an AM circuit supplied by Lemma~\ref{lemma:structural}. 

\begin{lemma}\label{lemma:smoothening}
Let $F: \bbR^m \to \bbR$ be a smooth convex function where
    \[ \sup_{x \in [-1, 1]^m} \norm{\nabla F(x)}_1 \leq L. \]
Let $D$ be an $m$-dimensional MVG vector with zero means, variances $1$ and arbitrary covariances.
Let $Z\sim \calN(0,I_{m})$ be independent of $D$, and let $G = \sqrt{\tau} Z + \sqrt{1-\tau}D$ for some $\tau \in [1/2,1]$.
Let $a\in \bbR^m$ be any vector and $\delta \in (0, 1/2]$.
Then,
\[ 
0 \leq \E[F(\sgn(a+G))]-\E[F(h_{a,\delta}(G))] \leq 
18L\delta \cdot (\|a\|_{\infty}+\sqrt{\ln 2m}).\]
\end{lemma}
\begin{proof}
We first prove that the lower bound follows from the convexity of $F$.
Indeed, let $G'$ be an MVG with the same law as $G$, drawn independently of $G$. 
Then, by the definition of $h_{a, \delta}$ and Jensen's inequality
we have 
\[
\E[F(h_{a,\delta}(G))]
= \E[F(\E[\sgn(a+\sqrt{1-\delta^2} G + \delta G') \mid G])]
\le \E[F(\sgn(a+\sqrt{1-\delta^2} G + \delta G'))],
\]
but the distribution of $a+\sqrt{1-\delta^2} G + \delta G'$ is exactly the same as that of $a+G$, thus the RHS equals $\E[F(\sgn(a+G))]$, completing the lower bound.

It remains to prove the upper bound.  
Define the random variable $S := \sgn(a+G)$. 
Since $F$ is smooth and convex, we have that everywhere
\begin{equation}F(S)-F(h_{a,\delta}(G)) \leq \nabla F(S) \cdot \bigl(S-h_{a,\delta}(G)\bigr).\end{equation}

The key point is that the RHS is the inner product of (i) a vector $\nabla F(S)$ with $\ell_1$-norm at most $L$ \emph{that only depends on $S$}, with (ii) another vector $(S-h_{a,\delta}(G))$ whose entries are typically small (of the order of $\delta$) where each entry still has a lot of randomness even conditioned on $S$.

So imagine we condition on $S$ and $D$. For $i \in [m]$, the $i$th coordinate of $G$ conditioned on $(S, D)$ is distributed as a truncated 1-dimensional Gaussian. We claim that after this conditioning, $h_{a,\delta, i}(G_i)$ is (on average) very close to $S_i$.
\begin{claim}\label{claim:bounded_deviation}
    $|S_i - \E[h_{a,\delta, i}(G_i) | S_i,D_i]| \leq 3\delta(1+|a_i|+|D_i|)$.
\end{claim}
Before we prove this claim, let's see why it finishes the proof. Indeed, assuming Claim \ref{claim:bounded_deviation}, then we have that
\begin{align*}
\E[F(S)-F(h_{a, \delta}(G))] &\leq \E[\nabla F(S) \cdot \bigl(S-h_{a,\delta}(G)\bigr)] \\
&= \E_{S,D}[\E[\nabla F(S) \cdot \bigl(S-h_{a,\delta}(G)\bigr)|S,D]]\\
&\leq \E_{S,D}[\nabla F(S) \cdot \E[\bigl(S-h_{a,\delta}(G)\bigr)|S,D]]\\
&\leq \E_{S,D}[\|\nabla F(S)\|_1 \cdot \|\E[\bigl(S-h_{a,\delta}(G)\bigr)|S,D]\|_{\infty}]\\
&\leq \E_{S,D}[\|\nabla F(S)\|_1 \cdot \max_i\{3\delta(1+|a_i|+|D_i|)\}]\\
&\leq L\cdot 3\delta \cdot (1+\|a\|_{\infty}+\E[\max_{i}|D_i|])\\
&\leq 3L\delta \cdot \bigl(1+\|a\|_{\infty}+4\sqrt{\ln 2m}\bigr) \tag{Fact~\ref{fact:exp_max}}\\
&\leq 18L\delta \cdot \bigl(\|a\|_{\infty}+\sqrt{\ln 2m}\bigr).\qedhere
\end{align*}
\end{proof}

\begin{proof}[Proof of Claim~\ref{claim:bounded_deviation}]
Let $Z_i\sim\mathcal{N}(0,1)$, let $\tau\in[1/2,1]$,
and let $d_i,a_i\in\mathbb{R}$ and $s_i\in \{-1,1\}$ be fixed. Define the random variable $Z'_i := \sqrt{\tau}\,Z_i+\sqrt{1-\tau}\,d_i+a_i$. Note that $Z'_i\sim\mathcal{N}(\mu,\sigma^2)$, where $\mu=\sqrt{1-\tau}\,d_i+a_i$ and $\sigma = \sqrt{\tau}$.

We need to show that
    \[ \bigl|s_i-\E[h_{a,\delta,i}(Z'_i-a_i)\,|\,\sgn(Z'_i)=s_i]\bigr| \leq 3\delta(1+|d_i|+|a_i|).\]
Without loss of generality, assume $s_i = 1$ (as negating $a,d,s$ maintains the same absolute value). Our new goal is to show that
\begin{equation}\label{eq:new_goal}
\E[1-h_{a,\delta,i}(Z'_i-a_i) | Z'_i>0]\le 3\delta (1+|d_i|+|a_i|).
\end{equation}
Let $p_+$ denote the density of $Z'_i$ conditioned on $Z'_i>0$.

To prove \Cref{eq:new_goal}, we first move to the following symmetric function
\[
    q_\delta(t)
    :=2\Phi\!\left(\frac{\sqrt{1-\delta^2}\,t}{\delta}\right)-1.
\]
Since $2\Phi-1$ is $\sqrt{2/\pi}$-Lipschitz, for every $t\in\bbR$,
\begin{align*}
    \left|h_{a,\delta,i}(t-a_i)-q_\delta(t)\right|
    &\le \sqrt{\frac{2}{\pi}}\,
         \frac{(1-\sqrt{1-\delta^2})|a_i|}{\delta}= \sqrt{\frac{2}{\pi}}\,
       \frac{\delta|a_i|}{1+\sqrt{1-\delta^2}}
    \le \delta|a_i|.
\end{align*}
Moreover, $1-q_\delta(t)\ge0$ for $t>0$, and
\[
    \int_0^\infty (1-q_\delta(t))\,dt
    =\frac{2\delta}{\sqrt{1-\delta^2}}
      \int_0^\infty(1-\Phi(u))\,du
    =\sqrt{\frac{2}{\pi}}\frac{\delta}{\sqrt{1-\delta^2}}
    \le\delta.
\]
Consequently, 
\begin{align*}
    \E\!\left[
        1-h_{a,\delta,i}(Z'_i-a_i)
        \,\middle|\,Z'_i>0
    \right]
    &\le \E[1-q_\delta(Z'_i)\mid Z'_i>0]
         +\delta|a_i|\\
    &\le \delta\sup_{t>0}p_+(t)+\delta|a_i|.
\end{align*}
We next prove that
\[ \sup_{t>0}p_+(t) \le \frac{1}{\sigma}+\frac{|\mu|}{\sigma^2}, \]
which will complete the proof as $\frac{1}{\sigma}+\frac{|\mu|}{\sigma^2} \le 2(1+|d_i|+|a_i|)$.

We split into two cases. If $\mu \ge 0$, then $\Pr[Z'_i>0]\ge 1/2$, and hence
\[
  p_+(t)
    \le 
    \frac{\exp\!\left(-(t-\mu)^2/(2\sigma^2)\right)}
         {\sigma\sqrt{2\pi}\,\Pr[Z'_i>0]}
    \le \frac{\sqrt{2/\pi}}{\sigma}
    \le \frac{1}{\sigma} \le \frac{1}{\sigma} + \frac{|\mu|}{\sigma^2}.
\]

Otherwise, $\mu<0$, and the conditional density $p_+$ is decreasing on $(0,\infty)$, with
\[
    \sup_{t>0} p_+(t)
    = \frac{1}{\sigma}
      \frac{e^{-b^2/2}}{\int_b^\infty e^{-t^2/2}\,dt}
\]
for $b=|\mu|/\sigma$. 
We claim that $\frac{e^{-b^2/2}}{\int_b^\infty e^{-t^2/2}\,dt}\le  b+1$.
Indeed, 
\[
\frac{e^{-b^2/2}}{b+1}
= \int_b^\infty -\frac{d}{dt}\!\left(\frac{e^{-t^2/2}}{t+1}\right)\,dt
= \int_b^\infty e^{-t^2/2}
  \underbrace{\frac{t^2+t+1}{(t+1)^2}}_{\le 1}\,dt
\le \int_b^\infty e^{-t^2/2}\,dt.
\]
Overall, in this case we also derive
\[
\sup_{t>0}p_+(t) \le \frac{b+1}{\sigma} = \frac{1}{\sigma} + \frac{|\mu|}{\sigma^2},
\]
which completes the proof.
\end{proof}

We are now ready to prove our main theorem, which shows that multivariate Gaussians with sufficiently weak covariance are indistinguishable from each other to smooth convex functions with low norms. 
\begin{theorem}\label{theorem:comparison}
Let $F: \bbR^{m} \to \bbR$ be a smooth convex function where
    \[ \sup_{x \in [-1, 1]^{m}} \norm{\nabla F(x)}_1 \leq L, \qquad \sup_{x \in [-1, 1]^{m}} \norm{\nabla^2F(x)}_1 \leq K, \]
where $L \leq m$. Let $D \sim \calN(0, \Sigma)$ be an $m$-dimensional Gaussian vector where $\Sigma_{ii} = 1$ and $\beta := \max_{i\neq j}|\Sigma_{ij}|$. Let $Z \sim \calN(0, I_{m})$ be an independent MVG, and let $G = \sqrt{1/2} D + \sqrt{1/2} Z$. Then, for every $a \in \bbR^{m}$ and $0 < \delta \leq 1/2$,
\begin{align*}
    \bigg|\E[F(\sgn(a+G))]-\E[F(\sgn(a+Z))]\bigg| \leq 400 L\delta \sqrt{\ln(2m)} + \frac{\beta K}{4\delta^2} + \frac{4}{m^{48}}\;.
\end{align*}
\end{theorem}
\begin{proof}[Proof of Theorem \ref{theorem:comparison}]
Fix $a$ and $\delta$. First, observe that by H\"older's inequality, we know that for all $x, y \in [-1, 1]^{m}$,
\begin{align*}
    |F(x)-F(y)| &= \left|\int_0^1 \nabla F(x+t(y-x)) \cdot (y-x) \,dt\right| \\
    &\leq \sup_{t \in [0, 1]} \|\nabla F(x+t(y-x))\|_1 \cdot \|y-x\|_{\infty} \leq 2L.
\end{align*}
For each coordinate $i$ where $|a_i| > 10\sqrt{\ln m}$, replace the $i$th coordinate of $\sgn(a+G)$ and of $\sgn(a+Z)$ with $\sgn(a_i)$. Each coordinate of $G$ and of $Z$ is standard normal, so
    \[ \Pr[\sgn(a_i+G_i) \neq \sgn(a_i)] \leq \Phi(-|a_i|) \leq e^{-a_i^2/2} \leq m^{-50}, \]
and the same bound holds for $Z$. A union bound and the Lipschitz bound $|F(x)-F(y)|\le 2L$ imply that each of $\E[F(\sgn(a+G))]$ and $\E[F(\sgn(a+Z))]$ changes by at most $2Lm^{-49} \le 2m^{-48}$.

After having fixed all coordinates where $|a_i| > 10\sqrt{\ln m}$, it is straightforward to see that $F$ remains a smooth convex function with the same norm bounds. Similarly, the covariance matrix of (the remaining coordinates of) $G$ satisfies the same conditions as before. It thus suffices to show that 
\begin{align*}
    \bigg|\E[F(\sgn(a+G))]-\E[F(\sgn(a+Z))]\bigg| \leq 400 L\delta \sqrt{\ln(2m)} + \frac{\beta K}{4\delta^2},
\end{align*}
assuming $|a_i| \leq 10\sqrt{\ln m}$ for all $i \in [m]$.

To interpolate between $Z$ and $G$ we introduce the following.
For $1/2 \leq \tau \leq 1$, denote the random variable $G(\tau) = \sqrt{\tau}Z+\sqrt{1-\tau}D$. Thus $G(1/2) \sim G$ while $G(1) \sim Z$. Our ultimate goal is (more or less) to smoothly interpolate between these endpoints under the function $F$.

The proof consists of two major steps. We begin by approximating $\sgn(a+G(\tau))$ by $h_{a,\delta}(G(\tau))$. By Lemma \ref{lemma:smoothening}, this smoothing is a good approximation of both endpoints under $F$, provided $F$ has low $\ell_1$-gradient norm.

Our second step is to show that once we have smoothened $\sgn(a+G(\tau))$ to $h_{a,\delta}(G(\tau))$, the distributions $G(1/2)$ and $G(1)$ are similar from the perspective of $F$:

\begin{lemma}\label{lemma:interpolation}
$\left|\E[F(h_{a,\delta}(G(1)))]-\E[F(h_{a,\delta}(G(1/2)))]\right| \leq \frac{\beta K}{4\delta^2}$.
\end{lemma}
\begin{proof}[Proof of Lemma \ref{lemma:interpolation}]
Define the function  $Q := F \circ h_{a,\delta}$ (which satisfies the conditions of Lemma \ref{lemma:smart_path} since all partial derivatives of $h_{a,\delta}$ are bounded for fixed $a, \delta$ and $F$ is smooth on $[-1, 1]^{m}$). 
Lemma \ref{lemma:smart_path} then gives
for $q(t) = \bbE[Q(G(t))]$ that 
\begin{align*}
    q'(t)
    &= \frac{1}{2} \sum_{i, j \in [m]}(I - \Sigma)_{ij}
          \E[\partial_{ij}Q(G(t))]\\
    &= \frac{1}{2} \sum_{i \neq j \in [m]} (-\Sigma_{ij})
          \E[\partial_{ij}Q(G(t))].
\end{align*}
For $i \neq j$, the chain rule gives
    \[ \partial_{ij} Q(x) = (\partial_{ij}F)(h_{a,\delta}(x)) \cdot h_{a,\delta,i}'(x_i) h_{a,\delta,j}'(x_j). \]
Thus,
\begin{align*}
    |q'(t)| &\leq \frac{\max_{i \neq j} |\Sigma_{ij}|}{2} \bbE\left[\sum_{i \neq j}|\partial_{ij}Q(G(t))|\right] = \frac{\beta}{2} \bbE\left[\sum_{i \neq j}|\partial_{ij}Q(G(t))|\right] \\
    &\leq\frac{\beta}{2\delta^2} \bbE\left[\sum_{i \neq j}|(\partial_{ij}F)(h_{a,\delta}(G(t)))|\right] \leq \frac{\beta K}{2\delta^2}.
\end{align*}
Integrating over $1/2 \leq t \leq 1$ and taking absolute values gives
    \[ \left|\E[F(h_{a,\delta}(G(1)))]-\E[F(h_{a,\delta}(G(1/2)))] \right| \leq \int_{1/2}^1 |q'(t)|\,dt \leq \frac{\beta K}{4\delta^2}, \]
as claimed.
\end{proof}

As Lemma \ref{lemma:smoothening} implies that for $\tau \in [1/2, 1]$,
    \[ 0 \leq \E[F(\sgn(a+G(\tau)))] - \E[F(h_{a,\delta}(G(\tau)))] \leq 
    18L\delta \cdot (\|a\|_{\infty}+\sqrt{\ln(2m)}) \le 200 L\delta \sqrt{\ln(2m)}, \]
we conclude that
\begin{align*}
    \bigg|\E[F(\sgn(a+G))]-\E[F(\sgn(a+Z))]\bigg| &= \bigg|\E[F(\sgn(a+G(1/2)))]-\E[F(\sgn(a+G(1)))]\bigg| \\
    &\leq \bigg|\E[F(\sgn(a+G(1/2)))]-\E[F(h_{a,\delta}(G(1/2)))]\bigg| 
    \\&\quad+ \bigg|\E[F(h_{a,\delta}(G(1/2)))]-\E[F(h_{a,\delta}(G(1)))]\bigg| 
    \\&\quad+ \bigg|\E[F(h_{a,\delta}(G(1)))]- \E[F(\sgn(a+G(1)))]\bigg|\\
    &\leq 400 L\delta \sqrt{\ln(2m)} + \frac{\beta K}{4\delta^2}
\end{align*}
\end{proof}

Next, we show that in fact one can compare $F(\sgn(D))$ to $F(\sgn(Z))$ directly without needing to apply noise to $D$. This is achieved by iterative application of \Cref{theorem:comparison}.

\begin{corollary}\label{cor:recursive}
Let $F: \bbR^{m} \to \bbR$ be a smooth convex function where
    \[ \sup_{x \in [-1, 1]^{m}} \norm{\nabla F(x)}_1 \leq L, \qquad \sup_{x \in [-1, 1]^{m}} \norm{\nabla^2F(x)}_1 \leq K, \]
where $L \leq m$. Let $D \sim \calN(0,\Sigma)$ be an $m$-dimensional Gaussian vector where $\Sigma_{ii} = 1$ and $\beta := \max_{i\neq j}|\Sigma_{ij}|$. Let $Z \sim \calN(0,I_{m})$ be an independent MVG. Then, for every $0 < \delta \leq 1/2$ and $T \in \bbN$,
\begin{align*}
    \bigg|\E[F(\sgn(D))]-\E[F(\sgn(Z))]\bigg| \leq T \cdot \left(400 L\delta \sqrt{\ln(2m)} + \frac{\beta K}{4\delta^2} + \frac{4}{m^{48}}\right) + 2^{-T/2} \cdot mL\;.
\end{align*}
\end{corollary}
\begin{proof}
Recall the definition $G(\tau) = \sqrt{\tau} Z + \sqrt{1-\tau}D$. We apply \Cref{theorem:comparison} iteratively to compare $G(0)$ and $G(1)$. For $i=0, 1,\ldots,T$, define the hybrid distribution $H^{(i)} := G(2^{-i})$ and define $H^{(T+1)} = G(0)$. We first note that
    \[ \E[F(\sgn(G(1)))] - \E[F(\sgn(G(0)))] =  \sum_{i=0}^{T} \left(\E[F(\sgn(H^{(i)}))] - \E[F(\sgn(H^{(i+1)}))]\right) \]
by a simple telescoping identity.

We begin by showing that for $0 \leq i \leq T-1$, 
    \[ \bigl|\E[F(\sgn(H^{(i)}))] - \E[F(\sgn(H^{(i+1)}))]\bigr|  \le 400 L\delta \sqrt{\ln(2m)} + \frac{\beta K}{4\delta^2} + \frac{4}{m^{48}}. \]
The case $i = 0$ is exactly comparing $G(1)$ to $G(1/2)$, which is proved in \Cref{theorem:comparison}.

For $i > 0$, note that
    \[ H^{(i)} \sim \sqrt{2^{-i}}Z + \sqrt{1-2^{-i}}D, \] 
and
    \[ H^{(i+1)} \sim \sqrt{2^{-(i+1)}}Z + \sqrt{2^{-(i+1)}}D' + \sqrt{1-2^{-i}}D, \]
where $D'$ is an independent copy of $D$. Here we use the fact that the sum of independent MVGs is an MVG. Now observe that we can think of first fixing $D = a$ and then comparing $\E[F(\sgn(H^{(i+1)}))|D=a]$ with $\E[F(\sgn(H^{(i)}))|D=a]$. But conditioned on $D = a$,
    \[ \sgn(H^{(i)}) = \sgn(\sqrt{2^{i}} H^{(i)}) = \sgn\left(Z + \sqrt{2^{i}(1-2^{-i})}a\right), \]
and
    \[ \sgn(H^{(i+1)}) = \sgn(\sqrt{2^{i}} H^{(i+1)}) = \sgn\left(\sqrt{1/2}Z +\sqrt{1/2}D' + \sqrt{2^{i}(1-2^{-i})}a\right), \]
so we see that we have again reduced to the case of \Cref{theorem:comparison} but now with the shift vector $\sqrt{2^{i}(1-2^{-i})}a$. By averaging over $a$ we get
\begin{align*}
\bigl|\E[F(\sgn(H^{(i+1)}))] - \E[F(\sgn(H^{(i)}))]\bigr| \le 400 L\delta \sqrt{\ln(2m)} + \frac{\beta K}{4\delta^2} + \frac{4}{m^{48}}.
\end{align*}

Finally, we compare $H^{(T)} = G(2^{-T})$ with $H^{(T+1)} = G(0)$. Indeed, for each $i \in [m]$,
    \[ H^{(T)}_i = \sqrt{2^{-T}} Z_i + \sqrt{1-2^{-T}}D_i,\qquad H^{(T+1)}_i=D_i\;. \]
Their correlation is $\sqrt{1-2^{-T}}$ and thus
    \[ \E[\sgn(H^{(T)}_i) \sgn(H^{(T+1)}_i)] = \tfrac{2}{\pi} \arcsin(\sqrt{1-2^{-T}}) \ge 1-2^{-T/2}, \]
and so the signs disagree with probability at most $2^{-T/2-1}$. Taking a union bound over all $m$ coordinates, we see that with probability at most $m2^{-T/2-1}$, $\sgn(H^{(T)}) \neq \sgn(H^{(T+1)})$. Furthermore, whenever the two vectors differ, $|F(\sgn(H^{(T)}))-F(\sgn(H^{(T+1)}))|\le 2L$ by the $\ell_1$-gradient norm of $F$.
Thus,
    \[ \bigl|\E[F(\sgn(H^{(T)}))]-\E[F(\sgn(H^{(T+1)}))]\bigr| \leq mL\,2^{-T/2}\;.\]
Summing the $T$ hybrid steps and this final comparison, and using $H^{(0)}=Z$ together with $H^{(T+1)}=D$, gives
\[
    \bigl|\E[F(\sgn(Z))]-\E[F(\sgn(D))]\bigr|
    \leq T\cdot\left(400 L\delta\sqrt{\ln(2m)}+\frac{\beta K}{4\delta^2}+\frac{4}{m^{48}}\right)+mL\cdot 2^{-T/2}.
\]
\end{proof}

Finally, we achieve the main result of this section: the Forrelation distribution $\calD_n$ is pseudorandom against $(d,L)$-AM circuits with  $d, L = \poly(n)$.

\begin{corollary}\label{cor:values}
For any $(d, L)$-AM circuit $C$ where $d, L = \poly(n)$,
    \[ \left|\E_{(x, y) \sim \calD_n}[C(x, y)] - \E_{(x, y) \sim \calU_n}[C(x, y)]\right| \leq 2^{-\Omega(n)}. \]
\end{corollary}
\begin{proof}
Set $\delta = N^{-1/8}$,  $\lambda = 1/\delta$, and $T = \lceil 10 \ln(2N) \rceil$.
Applying \Cref{lemma:structural} gives a smooth convex function $F$ such that $0 \leq F-C \leq \frac{dL \ln 2}{\lambda}$, $\sup_x \|\nabla F(x)\|_1 \leq L$, and $\sup_x \|\nabla^2 F(x)\|_1 \leq 2\lambda dL^2$. 

Note that $\sgn(Z) \sim \calU_n$ where $Z \sim \calN(0,I_{2N})$ and $\calD_n$ is distributed as the signs of a multivariate Gaussian with covariance matrix 
    \[ \Sigma = \begin{bmatrix} I_N & H_N \\ H_N & I_N \end{bmatrix}. \]
As the off-diagonal entries of $\Sigma$ have magnitude at most $\beta = 1/\sqrt{N}$, applying \Cref{cor:recursive} with $m=2N$ gives
\begin{align*}
    &\bigl|\E_{(x, y) \sim \calD_n}[C(x, y)] - \E_{(x, y) \sim \calU_n}[C(x, y)]\bigr| \\
    \leq \,\, &\bigl|\E_{(x, y) \sim \calD_n}[F(x, y)] - \E_{(x, y) \sim \calU_n}[F(x, y)]\bigr| + \frac{dL \ln 2}{\lambda} \\
    \leq \,\, &\frac{dL \ln 2}{\lambda} + T\cdot \left(400 L\delta \sqrt{\ln 2m} + \frac{\beta \cdot (2\lambda dL^2)}{4\delta^2} +  \frac{4}{m^{48}}\right)  + mL\cdot 2^{-T/2}\\
    = \,\, &\frac{\poly(n)}{2^{n/8}} = 2^{-\Omega(n)}.
\end{align*} 
\end{proof}

\begin{corollary}[Reminder of Theorem \ref{theorem:oracle_separation}]\label{cor:separation}
There exists a classical oracle $\calO$ relative to which $\BQP^{\calO} \not\subseteq \IP^{\calO}$.
\end{corollary}
The proof of Corollary \ref{cor:separation} follows by a straightforward diagonalization argument, which we include in Appendix \ref{sec:diag} for completeness.

