To analyze the eigenphases of $F_\pm(t)$ for small $t$, we extend these matrices to a complex parameter $z$ by defining $F_+(z):=Ve^{-izK}$ and $F_-(z):=V^\dagger e^{-izK}$. This allows us to apply the analytic perturbation result in \Cref{lem:quantitative-analytic-perturbation} to the isolated eigenvalues associated with $\ket{e_0}$ and $\ket{e_1}$. The following lemma characterizes the resulting eigenphases and shows that the linear term of their Taylor expansions is given by the corresponding energy expectations $\bra{x}H\ket{x}$ and $\bra{y}H\ket{y}$, respectively.

\begin{lemma}\label{lem:analytic}
The matrix $F_+(z)$ has an analytic eigenvector $\ket{\phi_{a,+}(z)}$ and corresponding analytic eigenvalue $\lambda_{a,+}(z)=e^{-i\theta_{a,+}(z)}$ for $a=0,1$. For $|z|<c/\Lambda$, the eigenvectors and eigenvalues satisfy
\begin{equation}\label{eq:eigen-perturbation}
    \norm{\ket{\phi_{a,+}(z)}-\ket{e_a}} \le C\Lambda |z|,\quad |\lambda_{a,+}(z)-\lambda_{a,+}(0)| \le C\Lambda |z|,
\end{equation}
where $c,C$ are universal constants. The same argument holds for $F_{-}(z)$, with eigenvector $\ket{\phi_{a,-}(z)}$ corresponding to eigenvalue $\lambda_{a,-}(z)=e^{-i\theta_{a,-}(z)}$.
Choose the phases analytically with $\theta_{a,\pm}(0)=\pm a\pi/2$.

With the value at $t=0$ defined by continuity, we have
\begin{equation}\label{eq:def-delta-a}
     \delta_a(t):=\frac{\theta_{a,+}(t)+\theta_{a,-}(t)}{2t} = \bra{e_a}K\ket{e_a}+\sum_{j=1}^\infty b_{a,j}t^{2j},\quad |b_{a,j}| \le C\Lambda(C\Lambda)^{2j}.
\end{equation}
\end{lemma}
\begin{proof}
    The proof is given in \Cref{app:analytic}.
\end{proof}

